export default async function collect({ propertyId, previous }, context) {
  const groups = [
    {
      dimension: "unifiedScreenName",
      metrics: ["screenPageViews", "activeUsers", "screenPageViewsPerUser", "eventCount"],
    },
    {
      dimension: "landingPagePlusQueryString",
      metrics: [
        "activeUsers",
        "engagedSessions",
        "engagementRate",
        "eventCount",
        "organicGoogleSearchAveragePosition",
        "organicGoogleSearchClickThroughRate",
        "organicGoogleSearchClicks",
        "organicGoogleSearchImpressions",
      ],
    },
    {
      dimension: "country",
      metrics: [
        "activeUsers",
        "newUsers",
        "engagementRate",
        "engagedSessions",
        "eventCount",
        "totalUsers",
        "sessions",
      ],
    },
  ];
  if (typeof propertyId !== "string" || !/^\d+$/.test(propertyId))
    throw Error("Configure a Google Analytics property ID");
  const day = new Date().toISOString().slice(0, 10),
    d = (base, n) =>
      new Date(Date.parse(base + "T00:00:00Z") + n * 86400000).toISOString().slice(0, 10),
    s = previous ?? { index: 0, offset: 0, day, tables: [[], [], [], [], [], []] };
  if (
    !Number.isSafeInteger(s.index) ||
    s.index < 0 ||
    s.index >= 6 ||
    !Number.isSafeInteger(s.offset) ||
    s.offset < 0 ||
    !Array.isArray(s.tables) ||
    s.tables.length !== 6 ||
    typeof s.day !== "string"
  )
    throw Error("Invalid report state");
  const g = groups[Math.floor(s.index / 2)],
    recent = s.index % 2 === 0,
    range = { startDate: d(s.day, recent ? -7 : -14), endDate: d(s.day, recent ? -1 : -8) },
    result = await context.actions.call("google_analytics.run_report", {
      propertyId,
      dateRanges: [range],
      dimensions: [g.dimension],
      metrics: g.metrics,
      keepEmptyRows: true,
      limit: 10000,
      offset: s.offset,
    });
  const r = result?.report;
  if (!r || !Array.isArray(r.rows)) throw Error("Invalid analytics response");
  const count = r.rowCount == null && r.rows.length === 0 && s.offset === 0 ? 0 : r.rowCount;
  if (
    !Number.isSafeInteger(count) ||
    count < 0 ||
    s.offset + r.rows.length > count ||
    (!r.rows.length && s.offset < count)
  )
    throw Error("Invalid analytics page count");
  const rows = r.rows.map((x) => {
    if (
      !Array.isArray(x.dimensionValues) ||
      x.dimensionValues.length !== 1 ||
      typeof x.dimensionValues[0] !== "string" ||
      !Array.isArray(x.metricValues) ||
      x.metricValues.length !== g.metrics.length ||
      x.metricValues.some((v) => typeof v !== "string")
    )
      throw Error("Invalid analytics row");
    return [x.dimensionValues[0], ...x.metricValues];
  });
  const tables = s.tables.map((x) =>
    Array.isArray(x)
      ? [...x]
      : (() => {
          throw Error("Invalid report table");
        })(),
  );
  tables[s.index].push(...rows);
  const offset = s.offset + rows.length,
    finished = offset === count,
    index = finished ? s.index + 1 : s.index;
  return { state: { index, offset: finished ? 0 : offset, day: s.day, tables }, more: index < 6 };
}

